package org.springframework.samples.petclinic.rest.error;

/**
 * Thrown when a submitted email address belongs to a disposable-email domain that is on the
 * blocklist. Carries the originally submitted value so the REST layer can report what was rejected.
 */
public class DisposableEmailDomainException extends RuntimeException {

    private final String rejectedValue;

    public DisposableEmailDomainException(String rejectedValue) {
        super("Email domain is on the disposable-domain blocklist, but was: " + rejectedValue);
        this.rejectedValue = rejectedValue;
    }

    public String getRejectedValue() {
        return this.rejectedValue;
    }
}

